using System;using System.Linq;using UnityEditor;using UnityEngine;using UnityEngine.UI;using VRC.SDKBase;using VRC.Udon;
namespace KominkaHillside.Editor {public static partial class KH_CourseWalkHarnessEditor{
 static UdonBehaviour premiumSelection,premiumWater;static Transform premiumBoard;static UdonBehaviour[] premiumTools;
 static void PremiumBind(){var st=GameObject.Find("KH_WashStation").transform;premiumSelection=st.Find("PremiumTools").GetComponent<UdonBehaviour>();premiumBoard=st.Find("PremiumSelectionBoard");premiumTools=st.Find("PremiumTools").GetComponentsInChildren<UdonBehaviour>(true).Where(u=>u.programSource!=null&&u.programSource.name=="KH_WashTool").ToArray();premiumWater=premiumTools.First(u=>Get<int>(u,"tool")==1);Networking.LocalPlayer.TeleportTo(st.TransformPoint(new Vector3(.8f,.1f,-.8f)),st.rotation);hwSyms.Clear();hwParams.Clear();}
 static void PremiumClick(string name){premiumBoard.Find(name).GetComponent<Button>().onClick.Invoke();}
 static void PremiumRecover(){if(premiumTools==null)return;foreach(var u in premiumTools)if(u!=null){u.SendCustomEvent("_onDrop");u.SetProgramVariable("debugHeldOverride",0);}premiumTools=null;premiumSelection=null;premiumWater=null;premiumBoard=null;}
 static void MakeWashPremiumCases(){wsReport.notCovered.Add("Premium: UI persistent listeners and local Owner request exercised. Pickup/Use events are injected; physical grip, two-client network, sound quality and Quest rendering remain NOT_TESTED.");
 if(WsGroup("premium")||WsGroup("premium-input"))PremiumInputCases();if(WsGroup("premium")||WsGroup("premium-other"))PremiumOtherCases();if(WsGroup("premium")||WsGroup("premium-other")||WsGroup("premium-free"))PremiumFreeCases();}
 static void PremiumInputCases(){var s=WsCase("P-selection-pulse-toggle",45);s.Add(WsDo(()=>{PremiumBind();PremiumClick("Set1");PremiumClick("Item0");PremiumClick("Take");}));s.Add(WsUntil(()=>Get<int>(premiumSelection,"selectedTool")==1&&Get<int>(premiumSelection,"_shownTool")==1,5,()=>"water gun selection via UI"));s.Add(WsDo(()=>{WsExpect(Get<int>(premiumSelection,"localResultCode")==0,"local owner replied success");premiumWater.SendCustomEvent("_onPickup");premiumWater.SendCustomEvent("_onPickupUseDown");WsExpect(Get<bool>(premiumWater,"_sprayOn"),"pulse starts immediately");}));s.Add(WsWait(.5));s.Add(WsDo(()=>{WsExpect(!Get<bool>(premiumWater,"_sprayOn")&&!Get<bool>(WsRef(premiumWater,"state") as UdonBehaviour,"spraying"),"pulse stops after 0.22 seconds");premiumWater.SendCustomEvent("_onDrop");PremiumClick("Item3");PremiumClick("Take");}));s.Add(WsUntil(()=>Get<int>(premiumSelection,"selectedTool")==4&&Get<int>(premiumSelection,"_shownTool")==4,5,()=>"same slot now shower"));s.Add(WsDo(()=>{premiumWater.SendCustomEvent("_onPickup");premiumWater.SendCustomEvent("_onPickupUseDown");premiumWater.SendCustomEvent("_onPickupUseUp");}));s.Add(WsWait(.5));s.Add(WsDo(()=>{WsExpect(Get<bool>(premiumWater,"_sprayOn"),"continuous shower stays on after release");premiumWater.SendCustomEvent("_onDrop");WsExpect(!Get<bool>(premiumWater,"_sprayOn"),"drop stops shower");WsNote("UI local owner request/ack; same-slot pulse-to-toggle; simulated pickup/Use/drop events");}));
 }
 static void PremiumOtherCases(){var s=WsCase("P-held-change-and-first-restore",20);s.Add(WsDo(()=>{PremiumBind();premiumSelection.SetProgramVariable("selectedTool",4);HwInvoke(premiumSelection,"_Apply","animate",false);}));s.Add(WsDo(()=>{premiumSelection.SetProgramVariable("_receivedState",true);premiumWater.SetProgramVariable("debugHeldOverride",1);premiumSelection.SetProgramVariable("selectedTool",2);premiumSelection.SetProgramVariable("revision",Get<int>(premiumSelection,"revision")+1);HwInvoke(premiumSelection,"_Apply","animate",false);WsExpect(Get<int>(premiumSelection,"_shownTool")==4,"held model retained during later race");premiumSelection.SetProgramVariable("_receivedState",false);HwInvoke(premiumSelection,"_Apply","animate",false);WsExpect(Get<int>(premiumSelection,"_shownTool")==2,"initial restoration applies even when held");premiumWater.SetProgramVariable("debugHeldOverride",0);WsNote("Timing states injected to exercise shared apply body; not a real LateJoin");}));
 s=WsCase("P-dryer-and-cosmetic-isolation",20);s.Add(WsDo(()=>{WsExpect(Get<float[]>(wsWash,"_hTime").Length==7,"compiled wash has separate dryer channel");var hit=HwTop(WsTorsoCenter(),part=>part==0||part==1,"premium cosmetic contact");var point=WsAt(hit).p;Networking.LocalPlayer.TeleportTo(point+new Vector3(0,0,-.5f),Quaternion.identity);foreach(var t in premiumTools.Where(u=>Get<int>(u,"finishKind")>0)){var foam=(float[])Get<float[]>(wsWash,"_foam").Clone();var wet=(float[])Get<float[]>(wsWash,"_wet").Clone();var dirt=(float[])Get<float[]>(wsWash,"_dirt").Clone();var before=Get<float[]>(wsWash,"_hTime").ToArray();HwInvoke(t,"_DebugSquirt","origin",point+Vector3.up*.15f,"direction",Vector3.down);WsExpect(foam.SequenceEqual(Get<float[]>(wsWash,"_foam"))&&wet.SequenceEqual(Get<float[]>(wsWash,"_wet"))&&dirt.SequenceEqual(Get<float[]>(wsWash,"_dirt"))&&before.SequenceEqual(Get<float[]>(wsWash,"_hTime")),"finish ray contact never enters wash cells/history");var fx=wsWash.transform.Find("PremiumFinish").GetComponent<UdonBehaviour>();WsExpect(Get<float>(fx,"_nextSend")>Time.time,"finish request reached cosmetic branch");fx.SetProgramVariable("_nextSend",0f);}WsNote("compiled Udon separate channel and ray-to-Stroke finish branch; dryer delta verified separately in Edit; no cosmetic visual acceptance");}));
 }
 static void PremiumFreeCases(){var s=WsCase("P-free-shower-regression",20);s.Add(WsDo(()=>{PremiumBind();PremiumClick("Set1");PremiumClick("Item0");PremiumClick("Take");}));s.Add(WsUntil(()=>Get<int>(premiumSelection,"selectedTool")>=0,5,()=>"positive control: premium selected before reset"));UdonBehaviour free=null;s.Add(WsDo(()=>{free=GameObject.Find("KH_WashShower_0").GetComponent<UdonBehaviour>();free.SendCustomEvent("_onPickup");free.SendCustomEvent("_onPickupUseDown");free.SendCustomEvent("_onPickupUseUp");}));s.Add(WsWait(.4));s.Add(WsDo(()=>{WsExpect(Get<bool>(free,"_sprayOn"),"free shower still toggles");free.SendCustomEvent("_onDrop");WsExpect(!Get<bool>(free,"_sprayOn"),"free shower stops on drop");WsExpect((Networking.LocalPlayer.GetPosition()-premiumSelection.transform.position).sqrMagnitude<=36f,"reset sender is within station range");PremiumClick("Reset");}));s.Add(WsWait(.7));s.Add(WsDo(()=>{WsExpect(Get<int>(premiumSelection,"selectedTool")==-1&&Get<int>(premiumSelection,"selectedBath")==-1&&Get<int>(premiumSelection,"localResultCode")==0,"reset clears premium selection with success reply");PremiumRecover();}));
 }
